--- a/registry/vaccines.go
+++ b/registry/vaccines.go
@@ -1,16 +1,42 @@
 package registry

 import (
	"encoding/json"
	"time"
 )

+type Vaccination struct {
+	Name string    `json:"name"`
+	Date time.Time `json:"date"`
+}
+
+type reply struct {
+	Items []Vaccination `json:"items"`
+}
+
+func Vaccinations(chip string) ([]Vaccination, error) {
+	resp, err := shared.Get("/pets/" + chip + "/vaccinations")
+	if err != nil {
+		return nil, err
+	}
+	defer resp.Body.Close()
+
+	var data reply
+	if err := json.NewDecoder(resp.Body).Decode(&data); err != nil {
+		return nil, err
+	}
+
+	return data.Items, nil
+}
